contract InvMutTest {
    C c;
    address owner;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a proposed difficulty value and run the sequence:
    // 1) Ensure this test contract is the owner by relying on deployment setup (the checker deploys C and passes it in).
    // 2) Call AdjustDifficulty(amount) and check that currentDifficulty() equals amount and the contract balance did not change.
    function run(uint256 amount) public payable {
        require(true);

        uint256 beforeBal = address(c).balance;
        // perform the state-changing call at top-level
        bool reverted;
        c.AdjustDifficulty(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;
        uint256 curDiff = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        // If the call did not revert, difficulty must equal amount and balance must be unchanged.
        // If it reverted, we cannot assume difficulty changed; then require that either it reverted or the properties hold.
        assert(reverted || (curDiff == amount && afterBal == beforeBal));
    }

    receive() external payable {}
}

