pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;
    address owner;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        vm.assume(true);
        uint256 beforeBal = address(c).balance;
        bool reverted;
        try c.AdjustDifficulty(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal = address(c).balance;
        uint256 curDiff;
        try c.currentDifficulty() returns (uint256 __r) { curDiff = __r; } catch { return; }
        assertTrue(reverted || (curDiff == amount && afterBal == beforeBal));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
